import sys; sys.path.insert(0, '/workspace/derm-teach/website/tools/v4/authoring'); from enr import *

E('herpes-zoster',
  kf=["Reactivation of **varicella-zoster virus (VZV)** from a sensory ganglion, causing a painful **unilateral dermatomal** vesicular rash.",
      "Lifetime risk about **1 in 4**; risk rises sharply after **50** and with immunosuppression.",
      "Pain or tingling often precedes the rash by 2–3 days; the rash crusts in 7–10 days.",
      "Antiviral (e.g. **aciclovir 800 mg five times daily for 7 days**) within 72 h for most adults over 50, or with eye, immunosuppression, severe pain or rash (CKS).",
      "**Ophthalmic zoster** (Hutchinson's sign) and immunocompromised patients need same-day assessment; offer the **shingles vaccine** (Shingrix) to eligible groups."],
  epi=[{"t": "**Who**", "sub": ["Anyone who has had chickenpox (or, rarely, the live varicella vaccine).", "Incidence rises with age: most cases after 50; up to half of people reaching 85 have had it."]},
       {"t": "**Risk factors**", "sub": ["Immunosuppression (HIV, cancer, chemotherapy, transplant, high-dose steroids, JAK inhibitors), older age, stress.", "Recurrence is uncommon (about 1–5%)."]}],
  aet=["Triggers sometimes identified: local trauma or surgery, radiotherapy, intercurrent infection.",
       "Zoster is **infectious** to people who have not had chickenpox (direct contact with fluid from blisters) until lesions crust."],
  myths=["**\"You can catch shingles from chickenpox\"**: contacts can catch **chickenpox** from shingles, not shingles itself.",
         "**\"It can't come back\"**: recurrence is uncommon but possible, especially with immunosuppression."],
  patho_lead="After chickenpox, VZV hides in **sensory ganglia**; when cell-mediated immunity falls, it reactivates and travels down the nerve.",
  mech=[("Latency after chickenpox", "VZV travels up sensory nerves from chickenpox lesions and stays **latent** in dorsal root or cranial nerve ganglia for decades.", "v3-hsv-ganglion.jpg", "Latent virus in a sensory ganglion, travelling along the nerve to the skin when it reactivates."),
        ("Reactivation", "Waning **VZV-specific T-cell immunity** (age, immunosuppression) lets the virus multiply in the ganglion, causing inflammation and **prodromal pain**."),
        ("Spread to the dermatome", "Virus moves down the sensory nerve to the skin supplied by that ganglion, producing grouped vesicles on a red base in **one dermatome**, not crossing the midline.", "v3-zoster-dermatome.jpg", "Unilateral band-like dermatomal rash on the trunk."),
        ("Nerve damage", "Ganglion and nerve inflammation can cause **post-herpetic neuralgia** and, with motor nerve involvement, weakness (e.g. Ramsay Hunt facial palsy)."),
        ("Healing", "Vesicles become pustules and crust in 7–10 days and heal in 2–4 weeks, sometimes with scarring and pigment change.")],
  histo=["Intraepidermal vesicles with **ballooning degeneration** and multinucleated giant keratinocytes (identical to herpes simplex).",
         "Diagnosis is clinical; **PCR** of vesicle fluid if atypical or immunocompromised."],
  special=[{"t": "**Immunocompromised**", "sub": ["Multi-dermatomal, disseminated or necrotic zoster; needs urgent specialist advice and often IV aciclovir."]},
           {"t": "**Pregnancy**", "sub": ["Zoster in pregnancy does not cause congenital varicella; seek specialist advice before prescribing antivirals."]},
           {"t": "**Skin of colour**", "sub": ["Erythema may be subtle; pigment change and keloid scarring after healing are more common."]}],
  comp=["**Post-herpetic neuralgia** (pain over 3 months): the commonest complication, more likely with age.",
        "**Herpes zoster ophthalmicus**: keratitis, uveitis, visual loss.", "**Ramsay Hunt syndrome**: facial palsy, ear vesicles, hearing loss and vertigo.",
        "Secondary bacterial infection, scarring.", "Dissemination, pneumonitis, hepatitis, encephalitis or stroke (vasculopathy), especially when immunocompromised."],
  prog=["Most immunocompetent patients recover fully in 2–4 weeks.", "PHN affects about 10–20%, more often over 60; it usually improves with time."],
  refs=[("UKHSA Green Book: Shingles", "https://www.gov.uk/government/publications/shingles-herpes-zoster-the-green-book-chapter-28a")],
  see_also=["herpes-simplex-labialis", "impetigo"])

E('viral-warts',
  kf=["Benign epidermal growths from **human papillomavirus (HPV)** infection of keratinocytes.",
      "Very common in **school-age children**; spread by direct contact, wet floors and autoinoculation.",
      "Common, plantar (verrucae), plane, filiform and periungual types; **thrombosed capillaries** (black dots) are typical.",
      "Most clear spontaneously: **half within 6 months in children, about 90% within 2 years**; treat only if painful or distressing.",
      "Options: **salicylic acid** paints and occlusion, cryotherapy; refer atypical, extensive, facial or immunosuppressed cases."],
  epi=[{"t": "**Who**", "sub": ["Up to a third of school-age children have warts at any time; less common in adults.", "Meat and fish handlers (HPV-7 'butcher's warts'), people with eczema and the **immunosuppressed** (transplant recipients) are at higher risk."]},
       {"t": "**Spread**", "sub": ["Direct contact, swimming pools and changing rooms, shaving, nail biting and picking; incubation up to 12 months."]}],
  aet=["**HPV types**: 1 (plantar myrmecia), 2 and 4 (common and plantar), 3 and 10 (plane), 7 (butchers), 27 and 57.",
       "Risk factors: barrier damage, moist skin, trauma, immunosuppression (e.g. azathioprine, ciclosporin, HIV)."],
  myths=["**\"Warts have roots\"**: they are purely epidermal; aggressive digging causes scars.",
         "**\"Children must stay out of swimming\"**: not necessary; covering verrucae with a plaster or sock is enough."],
  patho_lead="HPV infects the **basal layer** through tiny breaks in the skin and hijacks keratinocyte growth.",
  mech=[("Entry through micro-trauma", "Virus reaches **basal keratinocytes** through small breaks; maceration and trauma help it enter."),
        ("Viral genes drive proliferation", "Early viral proteins (E6, E7) push infected cells to keep dividing, producing **acanthosis, papillomatosis and hyperkeratosis**.", "v3-warts-skin-section.jpg", "A wart in section: thickened, folded epidermis with dilated capillaries in the papillae."),
        ("Virus made at the surface", "New virus is assembled in upper layers (**koilocytes**) and shed in skin flakes, spreading to other sites (lines of warts from scratching)."),
        ("Capillaries and black dots", "Dermal papillae with dilated capillaries extend up into the wart; clotted vessels show as **black dots**, unlike corns.", "v3-warts-vs-corn.jpg", "Verruca (black dots, interrupted skin lines) vs corn (central core, preserved skin lines)."),
        ("Immune clearance", "Cell-mediated immunity eventually recognises the virus and clears it, which is why most warts go without treatment.")],
  histo=["Papillomatosis, acanthosis and hyperkeratosis with parakeratosis over tips of papillae.",
         "**Koilocytes** (vacuolated keratinocytes with shrunken nuclei) and large keratohyaline granules in the upper epidermis.",
         "Biopsy only for atypical, persistent or bleeding lesions (exclude SCC in the immunosuppressed)."],
  special=[{"t": "**Immunosuppressed**", "sub": ["Warts are often numerous and resistant; any growing, painful or bleeding lesion in a transplant recipient needs urgent review (SCC)."]},
           {"t": "**Children**", "sub": ["Watchful waiting is reasonable; avoid painful treatments in young children."]}],
  comp=["Pain on walking (plantar warts); nail dystrophy (periungual).", "Spread to other sites and people; psychosocial distress.",
        "Scarring from destructive treatment.", "Rarely, malignant change (SCC) in immunosuppressed or epidermodysplasia verruciformis."],
  prog=["Children: about 50% clear in 6 months and 90% in 2 years without treatment.", "Adults' warts are more persistent and recur more often."],
  see_also=["perineal-dermatoses", "seborrhoeic-keratosis", "squamous-cell-carcinoma"])

E('candida-intertrigo',
  kf=["*Candida* (mostly *C. albicans*) infection of **warm, moist skin folds**.",
      "**Beefy red**, macerated fold with **satellite papules and pustules** at the edge; may involve the scrotum.",
      "Risk factors: obesity, diabetes, sweating, occlusion, incontinence, antibiotics, steroids, immunosuppression.",
      "Treat with **moisture control** plus a topical imidazole (e.g. clotrimazole) until 1–2 weeks after clearance; hydrocortisone 1% short term if inflamed.",
      "Recurrent or extensive: check **HbA1c**, review drugs and consider swabs."],
  epi=[{"t": "**Who**", "sub": ["Common at both ends of life: **infants** (napkin area) and older, less mobile adults.", "More common in hot, humid weather and in people with obesity or diabetes."]}],
  aet=["**Local**: heat, moisture, friction, occlusive clothing, incontinence, poor hygiene of folds.",
       "**Systemic**: **diabetes**, obesity, broad-spectrum antibiotics, systemic or topical steroids, immunosuppression (HIV, chemotherapy), pregnancy."],
  myths=["**\"All fold rashes are thrush\"**: irritant intertrigo, flexural psoriasis, erythrasma and tinea cruris look similar."],
  patho_lead="*Candida* is a normal commensal that becomes invasive when **local moisture or host defences** change.",
  mech=[("Moist, damaged skin", "Sweat and friction macerate the stratum corneum in folds, weakening the barrier (irritant intertrigo)."),
        ("Overgrowth and adhesion", "Commensal *Candida* multiplies in the warm, wet fold and adheres using surface adhesins.", "v3-candida-fold.jpg", "A macerated skin fold with Candida yeasts and hyphae invading the softened stratum corneum."),
        ("Hyphal invasion", "Yeasts switch to **pseudohyphae and hyphae**, releasing proteases and phospholipases that invade the stratum corneum and trigger neutrophil inflammation."),
        ("Satellite lesions", "Small pustules and papules form beyond the main edge where yeasts seed new follicles: the **satellite** sign.")],
  histo=["Yeasts and pseudohyphae in the stratum corneum (PAS stain) with neutrophils and subcorneal pustules.",
         "Diagnosis is clinical; swab or scrape for microscopy and culture if unsure or recurrent."],
  special=[{"t": "**Infants**", "sub": ["Candidal napkin dermatitis involves the skin creases (irritant napkin dermatitis spares them)."]},
           {"t": "**Skin of colour**", "sub": ["Erythema may look dusky or purple; post-inflammatory pigmentation is common."]}],
  comp=["Secondary bacterial infection; fissuring and pain.", "Spread to other folds, nails (chronic paronychia) or mouth.", "Persistent post-inflammatory pigmentation."],
  prog=["Responds well to treatment, but **recurs** unless moisture and risk factors are controlled."],
  see_also=["intertrigo", "tinea", "napkin-dermatitis", "psoriasis"])

E('onychomycosis',
  kf=["Fungal infection of the nail: **dermatophytes** (over 75%, mostly *T. rubrum*), moulds or *Candida*.",
      "Affects about **10%** of adults, rising to 20% over 60 and higher in diabetes; **toenails** far more than fingernails.",
      "Thickened, discoloured (white or yellow), crumbly nail with onycholysis and subungual debris.",
      "**Confirm with nail clippings** (microscopy and culture) before oral treatment; about half of abnormal nails are not fungal.",
      "Oral **terbinafine** is first line for dermatophyte infection (CKS); amorolfine lacquer for limited distal disease."],
  epi=[{"t": "**Prevalence**", "sub": ["About **10%** overall; up to **20% over 60** and 50% over 70; rare in children."]},
       {"t": "**Risk groups**", "sub": ["Older adults, **diabetes**, peripheral vascular disease, immunosuppression, psoriasis, athletes and communal-shower users.", "Often coexists with **tinea pedis**."]}],
  aet=["**Organisms**: dermatophytes (*T. rubrum*, *T. interdigitale*), non-dermatophyte moulds (about 10%; *Scopulariopsis*, *Fusarium*, *Aspergillus*), yeasts (fingernails with chronic paronychia).",
       "Predisposing: nail trauma, occlusive footwear, hyperhidrosis, smoking, genetic susceptibility; **biofilm** makes cure harder."],
  myths=["**\"It's just cosmetic\"**: it can cause pain, mobility problems and cellulitis risk in diabetes.",
         "**\"Every thick yellow nail is fungal\"**: trauma, psoriasis and ageing nails mimic it, so confirm first."],
  patho_lead="Fungi invade the **nail bed and plate keratin**, usually starting under the free edge.",
  mech=[("Entry", "Fungi from tinea pedis or the environment invade under the free edge (distal), from the surface (white superficial) or from the cuticle (proximal).", "v3-onychomycosis-patterns.jpg", "Patterns of invasion: distal-lateral subungual, white superficial, proximal subungual and total dystrophic."),
        ("Keratin digestion", "Keratinases digest nail-bed and plate keratin; the bed responds with **subungual hyperkeratosis**, lifting the plate (onycholysis)."),
        ("Spread and dystrophy", "Infection spreads proximally towards the matrix, causing thick, crumbly, discoloured nails; longitudinal 'spikes' and dermatophytomas (fungal balls) resist treatment."),
        ("Reservoir", "The infected nail reseeds the feet and groin, causing recurrent tinea.")],
  histo=["Fungal hyphae in the nail plate on **PAS-stained nail clipping** (sensitive test), with parakeratosis and neutrophils in the bed.",
         "Sample correctly: clip the affected nail back as far as possible and scrape subungual debris.", "v3-nail-sampling.jpg" and "See the sampling diagram in Diagnosis."],
  special=[{"t": "**Diabetes and peripheral arterial disease**", "sub": ["Treat more actively and refer to podiatry; thick nails cause pressure ulcers."]},
           {"t": "**Children**", "sub": ["Rare; check parents and siblings for tinea pedis."]}],
  comp=["Pain, difficulty walking and footwear problems.", "Secondary bacterial infection and **cellulitis** (especially diabetes).", "Recurrent tinea pedis and cruris (reservoir).", "Psychosocial distress."],
  prog=["Oral terbinafine gives the best cure rates, but nails take **6 months (fingers) to 12–18 months (toes)** to grow out.",
        "About **20–25% relapse** after treatment."],
  see_also=["tinea", "nail-signs", "paronychia", "psoriasis"])
